import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"10 Deploy, observe and recover your ticket business","description":"","frontmatter":{"docLocale":"en","counterpart":"/learn/production","contentType":"tutorial","prev":{"text":"09 HTTP checks and SDK","link":"/en/learn/verification"},"next":false},"headers":[],"relativePath":"en/learn/production.md","filePath":"en/learn/production.md"}'),n={name:"en/learn/production.md"};function o(r,e,l,p,d,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="_10-deploy-observe-and-recover-your-ticket-business" tabindex="-1">10 Deploy, observe and recover your ticket business <a class="header-anchor" href="#_10-deploy-observe-and-recover-your-ticket-business" aria-label="Permalink to &quot;10 Deploy, observe and recover your ticket business&quot;">​</a></h1><p>Starting state: the <code>jobs</code> checkpoint and lesson 09&#39;s public checks. Bring the same module to production and prove Tickets, files and queued tasks recover together, beyond a 200 health response.</p><p>You need a Docker host, reachable TLS domain, production configuration and reviewed source. Run at the course-copy root. Production creates persistent data and a public entrance; first read the <a href="./../tutorials/single-machine-production">deployment guide</a>.</p><h2 id="confirm-business-assembly" tabindex="-1">Confirm business assembly <a class="header-anchor" href="#confirm-business-assembly" aria-label="Permalink to &quot;Confirm business assembly&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saas-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saas-worker</span></span></code></pre></div><p>Both API Router paths and OpenAPI must include tickets. Worker must register the export Handler, Core file cleanup/maintenance and business export-expiry maintenance. The original default template has no tickets; building it does not produce course endpoints.</p><p>Save the copy&#39;s business changes into your own source revision. Course <code>.env</code>, Cookies and downloaded outputs are local development data, not production secret configuration.</p><h2 id="build-and-migrate-explicitly" tabindex="-1">Build and migrate explicitly <a class="header-anchor" href="#build-and-migrate-explicitly" aria-label="Permalink to &quot;Build and migrate explicitly&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/production/env.production.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>Set the real DOMAIN, Origin and database/storage secrets. API/Worker share the mail encryption key when mail is enabled. Build embeds migrations containing ticket tables. Startup orders healthy dependencies, migrate, storage-init, API/Worker/Caddy. API startup must not implicitly fill the schema.</p><p>Set request-terminal <code>BASE_URL</code> / <code>ORIGIN</code> to this HTTPS entrance. Repeat lesson 02 registration/creation and lesson 07 upload/download to create production-drill data. Deploying source does not transfer development data into production volumes.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/ready&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/course-http/cookies</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/tickets/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TICKET_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Expect readiness and Ticket reads to return 200 with the same authorization policy through TLS. Migration mismatch produces readiness 503; inspect image, source migrations and database, then migrate explicitly.</p><h2 id="correlate-requests-tasks-and-persisted-facts" tabindex="-1">Correlate requests, tasks and persisted facts <a class="header-anchor" href="#correlate-requests-tasks-and-persisted-facts" aria-label="Permalink to &quot;Correlate requests, tasks and persisted facts&quot;">​</a></h2><p>Retain request_id from creation/export and query Ticket, Core Job and Audit. tracing/Jobs/Audit wiring correlates requests with each Worker attempt, which has its own span after HTTP ends. Readable outputs and notifications establish commit; a trace alone cannot.</p><p>For local observation use <code>just dev-observability</code> in development and follow the <a href="./../tutorials/observability">observability guide</a> for logs, queues and storage. Domain needs no OTel dependency. Configure free observation ports if another profile already occupies them. Logs exclude bodies, Cookies, passwords and complete signed URLs; resource ids are not high-cardinality metric labels.</p><p>Redis/telemetry failure does not alter persisted Tickets. Exports can queue while Worker is stopped and resume claiming afterward. Tasks still honor leases, cancellation and publication-time authorization.</p><h2 id="back-up-and-restore-independently" tabindex="-1">Back up and restore independently <a class="header-anchor" href="#back-up-and-restore-independently" aria-label="Permalink to &quot;Back up and restore independently&quot;">​</a></h2><p>First run the ticket-specific local drill from the original template root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tutorial:recovery:check</span></span></code></pre></div><p>It requires local Docker and free ports 80/443. It creates an isolated course copy, image and two production Compose projects. Over localhost TLS it creates/updates tickets, uploads an attachment, queues an export with Worker stopped, and runs the real backup and independent restore commands. It compares restored fields/version, attachment bytes, JSON export and terminal notification. Cleanup removes its projects, volumes and private temporary data, retaining only a redacted report. This establishes local delivery and recovery; verify your public domain and production host with the steps below. See the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/check-tutorial-recovery.mjs" target="_blank" rel="noreferrer">ticket recovery entry</a>.</p><p>Enter a Maintenance Window using the <a href="./../tutorials/backup-restore">backup guide</a>, draining API before Worker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backups/ticket-course</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-down</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backups/ticket-course</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>Verify PASS in backup/restore reports. Production volumes remain while the restore project gets a new network/volumes. Archives include business schemas and Files ready objects but no secrets. Prepare the matching image/protected configuration instead of forcing new migrations onto a historical restored database.</p><p>Read the same production <code>TICKET_ID</code> after restore and compare fields/version. Download the attachment as in lesson 07 and compare sha256. Exports queued before backup should complete with restored Worker. Pending uploads follow TTL; one-hour exports stop signing downloads and business maintenance reclaims them.</p><p>Framework <code>production-smoke</code> / <code>production-restore-drill</code> checks knowledge journeys by default, not ticket assertions. Record your recovery outcomes separately; health/inventory cannot replace a business journey. Traffic switching is explicit, and deleting production volumes is not a port-conflict solution.</p><p>Previous: <a href="./verification">Public checks and SDK</a>. Continue with <a href="./../docs/">capability guides</a> to add business rules and independent delivery checks.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/learn/10-production.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,29)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
